// client/src/components/RouletteWheel.jsx

import React, { useRef, useEffect, useState } from 'react';

/**
 * 단순화된 클라이언트 전용 룰렛 컴포넌트.
 * 훅 호출 순서를 고정해서 "Rendered more hooks than during the previous render" 오류를 방지합니다.
 */
function RouletteWheel({ rewards, isSpinning, spinResult, rotationAngle, onSpin, disabled, spinCost }) {
	// Hooks: 항상 같은 순서로 호출
	const wheelRef = useRef(null);
	const wheelWrapperRef = useRef(null);
	const [segments, setSegments] = useState([]);

	const radius = 200;  // 룰렛 크기
	const center = radius + 10;

	// util
	const degToRad = (d) => (d * Math.PI) / 180;

	// 1) segments 초기화 (항상 useEffect로 처리)
	useEffect(() => {
		if (Array.isArray(rewards) && rewards.length > 0) {
			setSegments(rewards.map((r) => ({ label: r.name, key: r.name, type: r.type })));
			return;
		}

		const defaultRewards = [
			{ name: '이니스프리 10% OFF', type: 'COUPON', probability: 8 },
			{ name: '에뒤드 10% OFF', type: 'COUPON', probability: 8 },
			{ name: '토니모리 10% OFF', type: 'COUPON', probability: 6 },
			{ name: '미샤 10% OFF', type: 'COUPON', probability: 5 },
			{ name: '클리오 10% OFF', type: 'COUPON', probability: 6 },
			{ name: '롬앤 10% OFF', type: 'COUPON', probability: 7 },
			{ name: '라네즈 10% OFF', type: 'COUPON', probability: 5 },
			{ name: '올리브영 10% OFF', type: 'COUPON', probability: 7 },
			{ name: '10 포인트', type: 'POINTS', probability: 10 },
			{ name: '50 포인트', type: 'POINTS', probability: 8 },
			{ name: '꽽', type: 'NONE', probability: 30 },
		];
		setSegments(defaultRewards.map((r) => ({ label: r.name, key: r.name, type: r.type })));
	}, [rewards]);

	// 2) 회전 애니메이션 처리 (항상 존재)
	useEffect(() => {
		const wheel = wheelRef.current;
		if (!wheel || segments.length === 0) return;

		// 회전 애니메이션 적용
		wheel.style.transition = 'transform 4s cubic-bezier(.19,1,.22,1)';
		wheel.style.transform = `rotate(${rotationAngle}deg)`;
	}, [rotationAngle, segments.length]);

	// 3) spinResult 변경 시 축하 처리(비파괴적)
	useEffect(() => {
		if (!spinResult || spinResult.success === false) return;
		const wrapper = wheelWrapperRef.current;
		if (!wrapper) return;

		const colors = ['#ff6b6b', '#ffd166', '#6bf3ff', '#c39bff', '#ffd454', '#9ee0ff'];
		for (let i = 0; i < 24; i++) {
			const el = document.createElement('div');
			el.className = 'confetti';
			el.style.width = '8px';
			el.style.height = '12px';
			el.style.background = colors[i % colors.length];
			el.style.position = 'absolute';
			el.style.left = `${50 + (Math.random() - 0.5) * 60}%`;
			el.style.top = `${50 + (Math.random() - 0.5) * 40}%`;
			el.style.transform = `translate(-50%,-50%) rotate(${Math.random() * 360}deg)`;
			wrapper.appendChild(el);
			el.addEventListener('animationend', () => el.remove());
		}
	}, [spinResult]);

	// 렌더단에서 segments 비어있으면 로드 중 표시
	if (!segments || segments.length === 0) {
		return <div className="text-center p-8 text-gray-500">룰렛 데이터 로드 중...</div>;
	}

	const renderSegmentIcon = (type, size = 32) => {
		const scale = size / 18;
		if (type === 'POINTS') {
			return (
				<g className="segment-icon" transform={`translate(${-12},${-12}) scale(${scale})`}>
					<circle cx={12} cy={12} r={11} fill="#ffd454" stroke="#ffb84d" strokeWidth={1.5} />
					<text x={12} y={16} textAnchor="middle" fontSize={12} fontWeight={800} fill="#7a3e00">P</text>
				</g>
			);
		}
		if (type === 'COUPON') {
			return (
				<g className="segment-icon" transform={`translate(${-12},${-12}) scale(${scale})`}>
					<rect x={1} y={4} width={22} height={14} rx={3} fill="#ffd1f0" stroke="#ff9ad6" strokeWidth={1.5} />
					<text x={12} y={15} textAnchor="middle" fontSize={12} fontWeight={800} fill="#7a0b3a">%</text>
				</g>
			);
		}
		return null;
	};

	return (
		<div className="wheel-container">
			<div className="wheel-wrapper card" ref={wheelWrapperRef}>
				<div className="wheel-rotator" style={{ transformOrigin: 'center center', width: '100%', height: '100%' }}>
					<svg 
						ref={wheelRef}
						width={center * 2} 
						height={center * 2} 
						viewBox={`0 0 ${center * 2} ${center * 2}`} 
						style={{ 
							display: 'block', 
							margin: 'auto',
							transition: 'transform 4s cubic-bezier(.19,1,.22,1)',
							transform: `rotate(${rotationAngle}deg)`
						}}
					>
						<defs>
							<radialGradient id="segGloss" cx="30%" cy="20%" r="80%">
								<stop offset="0%" stopColor="rgba(255,255,255,0.28)" />
								<stop offset="60%" stopColor="rgba(255,255,255,0.06)" />
								<stop offset="100%" stopColor="rgba(255,255,255,0)" />
							</radialGradient>
						</defs>
						<g transform={`translate(${center},${center})`}>
							{segments.map((seg, i) => {
								const angle = 360 / segments.length;
								const start = i * angle;
								const path = `M 0 0 L ${radius * Math.cos(degToRad(start))} ${radius * Math.sin(degToRad(start))} A ${radius} ${radius} 0 0 1 ${radius * Math.cos(degToRad(start + angle))} ${radius * Math.sin(degToRad(start + angle))} Z`;
								const textAngle = start + angle / 2;
								const textX = (radius / 1.4) * Math.cos(degToRad(textAngle));
								const textY = (radius / 1.4) * Math.sin(degToRad(textAngle));
								const iconX = (radius / 2.1) * Math.cos(degToRad(textAngle));
								const iconY = (radius / 2.1) * Math.sin(degToRad(textAngle));
								const baseColor = seg.type === 'COUPON' ? '#ffd47a' : (seg.type === 'POINTS' ? '#9ee0ff' : '#f5f5f5');
								const accentColor = '#ddd';

								return (
									<g key={`${seg.key}-${i}`}>
										<path d={path} fill={baseColor} stroke={accentColor} strokeWidth={2} />
										<g transform={`translate(${iconX}, ${iconY}) rotate(${textAngle})`}>
											{renderSegmentIcon(seg.type)}
										</g>
										<text x={textX} y={textY} fill="#333" fontSize={16} fontWeight={700} textAnchor="middle" alignmentBaseline="middle" transform={`rotate(${textAngle} ${textX} ${textY})`}>
											{seg.label}
										</text>
									</g>
								);
							})}
						</g>
					</svg>

					{onSpin && (
						<div className="wheel-center">
							<div className="center-ring" style={{ width: 130, height: 130 }} />
							<button
								className={`heart-button ${disabled || isSpinning ? 'disabled' : ''} ${!isSpinning && !disabled ? 'pulse' : ''}`}
								style={{ width: 120, height: 120 }}
								onClick={(e) => {
									if (disabled || isSpinning) return;
									const btn = e.currentTarget;
									const rect = btn.getBoundingClientRect();
									const ripple = document.createElement('span');
									ripple.className = 'ripple';
									const size = Math.max(rect.width, rect.height);
									ripple.style.width = ripple.style.height = `${size}px`;
									ripple.style.left = `${e.clientX - rect.left - size/2}px`;
									ripple.style.top = `${e.clientY - rect.top - size/2}px`;
									btn.appendChild(ripple);
									ripple.addEventListener('animationend', () => ripple.remove());
									onSpin();
								}}
								disabled={disabled || isSpinning}
								aria-label="Spin the wheel"
							>
								<svg viewBox="0 0 24 24" width="72" height="72" className="heart-icon" xmlns="http://www.w3.org/2000/svg">
									<defs>
										<linearGradient id="heartGrad" x1="0" x2="1">
											<stop offset="0%" stopColor="#ff8a80" />
											<stop offset="100%" stopColor="#ff3d00" />
										</linearGradient>
									</defs>
									<path fill="url(#heartGrad)" d="M12 21s-7-4.35-9-6.5C-1 11 3 6 6 6c1.9 0 3 1.2 3 1.2S11.1 6 13 6c3 0 7 5 3 8.5C19 16.65 12 21 12 21z" />
								</svg>
								{spinCost != null && <div className="spin-cost" style={{ fontSize: 16, fontWeight: 800 }}>-{spinCost}</div>}
							</button>
						</div>
					)}

				</div>
				<div className="wheel-pointer bounce" style={{ position: 'absolute', left: '50%', top: -10, transform: 'translateX(-50%)', width: 0, height: 0, borderLeft: '20px solid transparent', borderRight: '20px solid transparent', borderTop: '32px solid #ff5252', zIndex:50, filter: 'drop-shadow(0 4px 8px rgba(255,82,82,0.5))' }} />
			</div>
		</div>
	);
}

export default RouletteWheel;
